My plan: a 2D planar U-bend — 10 mm passage throughout, legs from x=0 to x=0.120 m, bend centre (0, 0.02 m) with inner radius 10 mm and outer 20 mm (centreline 15 mm). I'll mesh it fully structured with `blockMesh` using three hex blocks (two straight legs plus a half-annulus bend made with arc edges), one cell thick in z with `empty` front/back patches. Coarse grading first.

```python
bdm = """/*--------------------------------*- C++ -*----------------------------------*\
  U-bend 2D duct, metres
\\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      blockMeshDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
scale 1;

vertices
(
    // bend block (front, z=0)
    (0      0      0)   // 0
    (0      0.01   0)   // 1
    (0      0.03   0)   // 2
    (0      0.04   0)   // 3
    // bend block (back, z=t)
    (0      0      0.005)  // 4
    (0      0.01   0.005)  // 5
    (0      0.03   0.005)  // 6
    (0      0.04   0.005)  // 7
    // lower leg right end
    (0.12   0      0)      // 8
    (0.12   0.01   0)      // 9
    (0.12   0      0.005)  // 10
    (0.12   0.01   0.005)  // 11
    // upper leg right end
    (0.12   0.03   0)      // 12
    (0.12   0.04   0)      // 13
    (0.12   0.03   0.005)  // 14
    (0.12   0.04   0.005)  // 15
);

blocks
(
    // bend: half annulus, inner r=0.01, outer r=0.02
    hex (0 1 2 3 4 5 6 7) (40 4 1) simpleGrading (1 1 1)
    // lower leg
    hex (0 8 9 1 4 10 11 5) (40 4 1) simpleGrading (1 1 1)
    // upper leg
    hex (2 12 13 3 6 14 15 7) (40 4 1) simpleGrading (1 1 1)
);

edges
(
    arc 1 2 (-0.01 0.02 0)        // inner, front
    arc 5 6 (-0.01 0.02 0.005)    // inner, back
    arc 3 0 (-0.02 0.02 0)        // outer, front
    arc 7 4 (-0.02 0.02 0.005)    // outer, back
);

boundary
(
    inlet
    {
        type patch;
        faces ((8 9 11 10));
    }
    outlet
    {
        type patch;
        faces ((12 13 15 14));
    }
    walls
    {
        type wall;
        faces
        (
            (0 3 7 4)        // bend outer
            (1 2 6 5)        // bend inner
            (0 8 10 4)       // lower leg bottom
            (1 9 11 5)       // lower leg top
            (2 12 14 6)      // upper leg bottom
            (3 13 15 7)      // upper leg top
        );
    }
    frontAndBack
    {
        type empty;
        faces
        (
            (0 1 2 3)
            (4 7 6 5)
            (0 8 9 1)
            (4 5 11 10)
            (2 12 13 3)
            (6 7 15 14)
        );
    }
);
"""
import os
os.makedirs("system", exist_ok=True)
open("system/blockMeshDict","w").write(bdm)
import subprocess
print(subprocess.run(["blockMesh"], capture_output=True, text=True).stdout[-800:])
```
